<div class="page-head"><h1>Groups</h1></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Group</th><th>Created by</th><th>Members</th><th>Plans</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $g): ?><tr><td><strong><?= e($g['name']) ?></strong><br><span class="muted small"><?= e($g['code']) ?> · <?= e($g['currency']) ?></span></td><td><?= e($g['creator']) ?></td><td><?= (int)$g['members'] ?></td><td><?= (int)$g['plans'] ?></td><td><?= badge($g['status']) ?></td>
<td><?php if (in_array($g['status'], ['active', 'suspended'], true)): ?><form class="mini-form" method="post" action="/admin/groups/<?= (int)$g['id'] ?>/status" data-confirm="<?= $g['status'] === 'active' ? 'Suspend this group? Members will be unable to make payments.' : 'Reactivate this group?' ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $g['status'] === 'active' ? 'suspended' : 'active' ?>"><div class="field"><label class="sr-only" for="gr<?= (int)$g['id'] ?>">Reason</label><input id="gr<?= (int)$g['id'] ?>" name="reason" placeholder="Reason" required></div><button class="btn small ghost"><?= $g['status'] === 'active' ? 'Suspend' : 'Reactivate' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
